select * from mes_wip_timeout_handle
WHERE del_flag='0' AND factory_code=#{query.factoryCode}

    AND config_code = #{query.configCode}


    AND line_code = #{query.lineCode}


    AND route_code = #{query.routeCode}


    AND product_code = #{query.productCode}


    AND task_code LIKE CONCAT('%', #{query.taskCode}, '%')


    AND status = #{query.status}


    AND alert_level = #{query.alertLevel}


    AND transfer_code = #{query.transferCode}

order by create_time desc
